css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .board { position: absolute; inset: 0; border-radius: 10px; background: color-mix(in srgb, var(--accent) 15%, transparent); box-shadow: inset 0 0 0 4px color-mix(in srgb, var(--accent) 55%, transparent); animation: maze-tilt calc(var(--loader-speed) * 4) ease-in-out infinite; }
.loader span { position: absolute; height: 6%; border-radius: 3px; background: var(--accent); }
.loader span:nth-of-type(1) { left: 10%; top: 26%; width: 62%; }
.loader span:nth-of-type(2) { right: 10%; top: 52%; width: 62%; }
.loader span:nth-of-type(3) { left: 10%; top: 76%; width: 62%; }
.loader i { position: absolute; width: 14%; height: 14%; border-radius: 50%; background: radial-gradient(circle at 36% 32%, color-mix(in srgb, #fff 55%, var(--accent-2)), var(--accent-2)); box-shadow: 0 2px 5px color-mix(in srgb, #000 35%, transparent); animation: maze-roll calc(var(--loader-speed) * 4) cubic-bezier(.45, 0, .55, 1) infinite; }
@keyframes maze-tilt { 0%, 100% { transform: rotate(-3deg); } 25% { transform: rotate(2deg); } 50% { transform: rotate(3deg); } 75% { transform: rotate(-2deg); } }
@keyframes maze-roll { 0% { left: 8%; top: 8%; } 22% { left: 76%; top: 8%; } 46% { left: 76%; top: 34%; } 50% { left: 8%; top: 34%; } 72% { left: 8%; top: 60%; } 76% { left: 76%; top: 60%; } 96%, 100% { left: 76%; top: 84%; } }
